window.RP_SESSION={"id":"S-7495f685e22c","messages":[{"id":"RP-II-0197976","time":"2026-09-20T20:04:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"이제는 조금 오래된 기억입니다.\n\n이제는 이 세상에 오직 저만이 기억하는 것이기도 합니다.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197977","time":"2026-09-20T20:04:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-fc30259aa580"]},{"id":"RP-II-0197978","time":"2026-09-20T20:05:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"‘ 오빠! 나도 언젠가 아빠랑 오빠처럼\n마법사가 될 수 있을까? ’","characters":["P-fc30259aa580"]},{"id":"RP-II-0197979","time":"2026-09-20T20:05:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"“ 그럼, 당연하지.\n어쩌면 넌 나와 아버지 그 이상의\n정말 위대한 마법사가 될 수 있을 지도 몰라! ”","characters":["P-fc30259aa580"]},{"id":"RP-II-0197980","time":"2026-09-20T20:05:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"‘ 치~ 맨날 막내한테만 칭찬 만땅이지! ’","characters":["P-fc30259aa580"]},{"id":"RP-II-0197981","time":"2026-09-20T20:06:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"“ 그럴리가~ 너는 워낙에 영특해서\n이미 세계의 목소리를 들을 수 있는 경지에 올랐잖니! ”","characters":["P-fc30259aa580"]},{"id":"RP-II-0197982","time":"2026-09-20T20:07:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"“ 너희가 이렇게 하루 하루 커가는 것을 보는게\n내게 있어 얼마나 큰 축복인지 모른단다. ”","characters":["P-fc30259aa580"]},{"id":"RP-II-0197983","time":"2026-09-20T20:07:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":".\n.\n.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197984","time":"2026-09-20T20:07:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"사진","characters":["P-fc30259aa580"]},{"id":"RP-II-0197985","time":"2026-09-20T20:07:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"“ 그래, 그 모습을 보는 것은\n내게 있어 정말 큰 축복이나 다름 없었단다. ”","characters":["P-fc30259aa580"]},{"id":"RP-II-0197986","time":"2026-09-20T20:07:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"이제는 들을 수 없는 그 목소리를","characters":["P-fc30259aa580"]},{"id":"RP-II-0197987","time":"2026-09-20T20:08:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"오늘도 천천히 떠올리고, 다짐합니다.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197988","time":"2026-09-20T20:08:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"“ 그러니, 조금만 더 응원해 주렴.\n너희와 같은 작은 가능성이 한껏 피어날 수 있길.\n그리고, 이 오라버니의 손길이\n그들에게 미약하게나마 도움이 될 수 있길. “","characters":["P-fc30259aa580"]},{"id":"RP-II-0197989","time":"2026-09-20T20:09:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"” 그러니, 조금만 더 기다려주렴.\n너희와 바로 함께할 수 없는 이 오빠를 용서하고,\n언젠가 너희에게 돌아가는 그 날\n이 오빠에게 말해주렴. “","characters":["P-fc30259aa580"]},{"id":"RP-II-0197990","time":"2026-09-20T20:09:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"” 이 모든 기억과 책무를 짊어진 채\n정말 열심히 살았노라고. “","characters":["P-fc30259aa580"]},{"id":"RP-II-0197991","time":"2026-09-20T20:10:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"어머니, 아버지.\n조금 더 나이를 먹으면 언젠가\n두 분의 나이를 제가 따라잡는 날이 오겠지요.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197992","time":"2026-09-20T20:10:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"부디, 두 분 앞에 서는 그 날에\n한 점의 부끄럼 없이 활짝 웃을 수 있길.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197993","time":"2026-09-20T20:11:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"최선을 다해 노력하고,\n미력한 힘이 빛을 발할 수 있도록 쥐어짜낼 테니.\n응원해주시고, 기다려주세요.\n보고싶습니다. 많이.","characters":["P-fc30259aa580"]},{"id":"RP-II-0197994","time":"2026-09-20T20:11:00+09:00","room":"RP II","name":"실론 아마우로스","profile":"실론 아마우로스","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-fc30259aa580"]},{"id":"RP-II-0197995","time":"2026-09-20T20:11:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"-fin","characters":[]},{"id":"RP-II-0197996","time":"2026-09-20T20:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"unresolved","type":"dialogue","body":"!독백","characters":[]},{"id":"RP-II-0197997","time":"2026-09-20T20:43:00+09:00","room":"RP II","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"조용히, 피어오르는\n또 다른 누군가의 이야기.\n\n※해당 RP는 중참이 불가합니다.\n※중참 희망시 해당 기입자께 문의 바랍니다.","characters":[]},{"id":"RP-II-0197998","time":"2026-09-20T20:43:00+09:00","room":"RP II","name":"라이티티아","profile":"라이티티아","identity":"unresolved","type":"dialogue","body":"https://youtu.be/TlRLhOvdKYA?si=AobpBZvG92nM0ykC","characters":[]}]};
